package io.github.jesterportfolio.hearth.persistence;

import java.util.*;import java.util.concurrent.*;import java.sql.*;import javax.sql.DataSource;
import io.github.jesterportfolio.hearth.economy.*;import io.github.jesterportfolio.hearth.survival.housing.*;import static io.github.jesterportfolio.hearth.survival.housing.HousingState.*;import io.github.jesterportfolio.hearth.inventory.*;

/** 새 소유 복사 PG에서만 호출하는 주택 결제/권한 실패·경합 검사입니다. Player는 만들지 않습니다. */
public final class HousingDatabaseChecks{
 private static <T>T await(CompletionStage<T> f)throws Exception{return f.toCompletableFuture().get(12,TimeUnit.SECONDS);}private static void check(boolean v,String n){if(!v)throw new IllegalStateException(n);System.out.println("HEARTH_HOUSING_DB_CHECK PASS "+n);System.out.flush();}private static void reject(CompletionStage<?> f)throws Exception{try{await(f);throw new IllegalStateException("EXPECTED_REJECTION");}catch(ExecutionException expected){}}
 private static String result(CompletionStage<?> f)throws Exception{return await(f.handle((v,e)->e==null?"OK":InventorySaveSession.code(e)));}
 private static HousingSettings settings(String version,long base){return new HousingSettings(new HousingSettings.Catalog(version,List.of(new HousingSettings.Tier("small",32,base),new HousingSettings.Tier("medium",64,base*4),new HousingSettings.Tier("large",128,base*16))),true,true,8,2,300,8,List.of(new HousingSettings.Plot("first",16,0,16,32),new HousingSettings.Plot("second",16,18,16,32)));}
 public static void run(DataSource source,Connection c)throws Exception{
  var p=new Properties();try(var r=HousingDatabaseChecks.class.getResourceAsStream("/economy-demo.properties")){p.load(new java.io.InputStreamReader(r,java.nio.charset.StandardCharsets.UTF_8));}p.setProperty("fixture-balance","0");var content=EconomyContent.parse(p);var db=PostgresProgressStore.forModules(source,f->{});var e=new EconomyStore(db,content);await(e.migrate());UUID realm=UUID.randomUUID();await(e.openNativeRealm(realm,UUID.randomUUID(),"c".repeat(64),1,true));var store=new HousingStore(db,e,realm,settings("first",100));await(store.open());reject(e.requireNoHousing(realm));check(true,"initialized_housing_cannot_be_silently_disabled");var owner=e.context(realm,UUID.randomUUID());var member=e.context(realm,UUID.randomUUID());var visitor=e.context(realm,UUID.randomUUID());var other=e.context(realm,UUID.randomUUID());var payload=InventoryPayload.pack(new byte[41][]);for(var actor:List.of(owner,member,visitor,other)){await(e.ensureAccount(actor,payload));try(var s=c.prepareStatement("UPDATE hearth_economy.account SET balance=100000 WHERE realm_id=? AND player_uuid=?")){s.setObject(1,realm);s.setObject(2,actor.playerId());s.executeUpdate();}}
  UUID id=UUID.randomUUID();var first=store.reserve(owner,id,0,-1,()->true);var second=store.reserve(owner,UUID.randomUUID(),0,-1,()->true);String a=result(first),b=result(second);check(a.equals("OK")&&!b.equals("OK"),"one_owner_concurrent_purchase_has_one_reservation");var request=await(first);check(await(e.account(owner)).balance()==100000,"reservation_never_debits_money");reject(store.reserve(member,id,0,-1,()->true));check(true,"request_id_is_bound_to_original_owner");
  UUID world=UUID.randomUUID();await(store.prepared(owner,request,world));reject(store.prepared(owner,request,UUID.randomUUID()));check(true,"prepared_world_identity_cannot_be_replaced");reject(store.commit(owner,request,()->true,EconomyStore.Probe.ROLLBACK));check(await(e.account(owner)).balance()==100000&&await(store.snapshot()).owned(owner.playerId()).orElseThrow().phase()==Phase.PREPARING,"real_SQL_23514_rolls_back_wallet_house_and_receipt_together");reject(store.commit(owner,request,()->false,EconomyStore.Probe.NONE));check(await(e.account(owner)).balance()==100000,"revoked_request_cannot_charge_wallet");
  reject(store.commit(owner,request,()->true,EconomyStore.Probe.COMMIT_UNKNOWN));var paid=await(store.inspect(owner,id)).orElseThrow();check(paid.paid()&&await(e.account(owner)).balance()==99900&&await(store.snapshot()).owned(owner.playerId()).orElseThrow().phase()==Phase.APPLYING,"unknown_commit_retains_one_paid_receipt_and_closed_house");await(store.commit(owner,request,()->true,EconomyStore.Probe.NONE));check(await(e.account(owner)).balance()==99900,"repeat_commit_does_not_charge_again");var active=await(store.activate(owner,request));check(active.phase()==Phase.ACTIVE&&active.world().equals(world)&&await(e.account(owner)).inventory().payload().equals(payload),"activation_preserves_native_inventory_payload_and_world_identity");
  var expand=await(store.reserve(owner,UUID.randomUUID(),1,active.revision(),()->true));check(expand.cost()==300,"expansion_uses_tier_difference_only");await(store.prepared(owner,expand,world));await(store.commit(owner,expand,()->true,EconomyStore.Probe.NONE));active=await(store.activate(owner,expand));check(active.width()==64&&active.world().equals(world)&&await(e.account(owner)).balance()==99600,"expansion_keeps_original_world_and_total_price");
  var changed=new HousingStore(db,e,realm,settings("second",200));await(changed.open());var next=await(changed.reserve(owner,UUID.randomUUID(),2,active.revision(),()->true));check(next.cost()==1200&&next.version().equals("first"),"new_price_version_does_not_reprice_existing_world");await(changed.prepared(owner,next,world));await(changed.commit(owner,next,()->true,EconomyStore.Probe.NONE));active=await(changed.activate(owner,next));long rev=active.revision();reject(changed.invite(other,active.id(),rev,member.playerId(),Role.RESIDENT,()->true));await(changed.invite(owner,active.id(),rev,member.playerId(),Role.RESIDENT,()->true));active=await(changed.snapshot()).owned(owner.playerId()).orElseThrow();var acceptA=changed.accept(member,active.id(),active.revision(),true,()->true);var acceptB=changed.accept(member,active.id(),active.revision(),true,()->true);check(Set.of(result(acceptA),result(acceptB)).size()==2,"concurrent_invitation_acceptance_has_one_revision_winner");active=await(changed.snapshot()).owned(owner.playerId()).orElseThrow();await(changed.invite(owner,active.id(),active.revision(),visitor.playerId(),Role.VISITOR,()->true));active=await(changed.snapshot()).owned(owner.playerId()).orElseThrow();await(changed.accept(visitor,active.id(),active.revision(),true,()->true));var snap=await(changed.snapshot());active=snap.owned(owner.playerId()).orElseThrow();check(snap.build(member.playerId(),active)&&snap.enter(visitor.playerId(),active)&&!snap.build(visitor.playerId(),active),"accepted_resident_and_visitor_have_distinct_permissions");var accessPolicy=io.github.jesterportfolio.hearth.survival.skills.WorldAccessPolicy.unrestricted();check(accessPolicy.evaluate(io.github.jesterportfolio.hearth.survival.skills.WorldAccessPolicy.Role.PRIVATE_HOME,snap.enter(visitor.playerId(),active),io.github.jesterportfolio.hearth.survival.skills.WorldAccessPolicy.Levels.unavailable()).allowed()&&!accessPolicy.evaluate(io.github.jesterportfolio.hearth.survival.skills.WorldAccessPolicy.Role.PRIVATE_HOME,snap.enter(other.playerId(),active),io.github.jesterportfolio.hearth.survival.skills.WorldAccessPolicy.Levels.unavailable()).allowed(),"skills_gate_preserves_PG_accepted_visitor_and_denies_foreign_actor");reject(changed.remove(other,active.id(),active.revision(),member.playerId(),()->true));await(changed.remove(member,active.id(),active.revision(),member.playerId(),()->true));snap=await(changed.snapshot());active=snap.owned(owner.playerId()).orElseThrow();check(!snap.enter(member.playerId(),active),"resident_can_leave_without_owner_and_loses_access");check(!accessPolicy.evaluate(io.github.jesterportfolio.hearth.survival.skills.WorldAccessPolicy.Role.PRIVATE_HOME,snap.enter(member.playerId(),active),io.github.jesterportfolio.hearth.survival.skills.WorldAccessPolicy.Levels.unavailable()).allowed(),"skills_gate_denies_after_real_PG_membership_revocation");
  var plotA=changed.claimPlot(member,()->true);var plotB=changed.claimPlot(visitor,()->true);check(!await(plotA).equals(await(plotB)),"concurrent_free_plot_claims_are_distinct");check(await(changed.claimPlot(member,()->true)).equals(await(plotA)),"repeat_plot_claim_is_idempotent");reject(changed.claimPlot(other,()->true));check(await(changed.snapshot()).plots().size()==2,"full_plot_pool_preserves_existing_assignments");reject(changed.invite(new ServerProgressAccess().forVerifiedServerLink(realm,owner.playerId()),active.id(),active.revision(),other.playerId(),Role.RESIDENT,()->true));check(true,"foreign_context_cannot_administer_owned_world");
  String hash;try(var s=c.createStatement();var r=s.executeQuery("SELECT checksum FROM hearth_economy.version WHERE version=8")){r.next();hash=r.getString(1);}try(var s=c.createStatement()){s.execute("UPDATE hearth_economy.version SET checksum='housing-fixture-mismatch' WHERE version=8");}var mismatch=PostgresProgressStore.forModules(source,f->{});reject(new EconomyStore(mismatch,content).migrate());await(mismatch.closeAsync());try(var s=c.prepareStatement("UPDATE hearth_economy.version SET checksum=? WHERE version=8")){s.setString(1,hash);s.executeUpdate();}check(await(changed.snapshot()).owned(owner.playerId()).orElseThrow().world().equals(world),"E008_checksum_mismatch_rejects_without_replacing_original_data");await(db.closeAsync());
 }
}
